"use client";

import React, { useState } from "react";
import { 
  Calendar, Clock, Trash2, Edit2, CheckCircle2, 
  XCircle, AlertCircle, ArrowUpRight, ShieldCheck, 
  Plane, Stethoscope, Briefcase, ChevronRight
} from "lucide-react";

// --- MOCK DATA & CONFIG ---
const LEAVE_BALANCES = [
  { id: "annual", label: "Annual", used: 10, total: 18, icon: Plane, color: "text-blue-500", bg: "bg-blue-500/10" },
  { id: "sick", label: "Sick", used: 4, total: 12, icon: Stethoscope, color: "text-rose-500", bg: "bg-rose-500/10" },
  { id: "casual", label: "Casual", used: 2, total: 6, icon: Briefcase, color: "text-amber-500", bg: "bg-amber-500/10" },
];

const MY_REQUESTS = [
  {
    id: "LR-001",
    type: "Sick Leave",
    category: "sick",
    start: "2026-02-10",
    end: "2026-02-12",
    days: 3,
    reason: "Scheduled dental surgery and recovery period.",
    status: "Pending",
    applied: "2026-01-24",
    approvers: ["Sarah J.", "HR Dept"]
  },
  {
    id: "LR-002",
    type: "Annual Leave",
    category: "annual",
    start: "2026-04-05",
    end: "2026-04-10",
    days: 5,
    reason: "Family trip to Japan. Flights are booked.",
    status: "Approved",
    applied: "2026-01-15",
    approvers: ["Sarah J.", "HR Dept"]
  },
  {
    id: "LR-003",
    type: "Casual Leave",
    category: "casual",
    start: "2025-12-20",
    end: "2025-12-20",
    days: 1,
    reason: "Personal errands.",
    status: "Rejected",
    applied: "2025-12-18",
    approvers: ["Sarah J."]
  }
];

export default function ProductivityManageAbsence() {
  const [selectedId, setSelectedId] = useState(MY_REQUESTS[0].id);
  const selectedReq = MY_REQUESTS.find(r => r.id === selectedId) || MY_REQUESTS[0];

  // Helpers
  const getDay = (d: string) => new Date(d).getDate();
  const getMonth = (d: string) => new Date(d).toLocaleString('default', { month: 'short' });
  const getBalance = (cat: string) => LEAVE_BALANCES.find(b => b.id === cat) || LEAVE_BALANCES[0];

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Approved': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case 'Rejected': return 'text-rose-600 bg-rose-50 border-rose-100';
      default: return 'text-amber-600 bg-amber-50 border-amber-100';
    }
  };

  return (
    <div className="h-screen w-full bg-[#fafafa] dark:bg-[#050505] font-sans text-slate-800 dark:text-slate-200 flex flex-col overflow-hidden p-4 gap-4">
      
      {/* 1. TITLE ROW (Matches Request Page) */}
      <div className="flex-none flex items-center justify-between px-2">
         <h1 className="text-xl font-black text-slate-900 dark:text-white tracking-tight">Manage Absence</h1>
         <div className="flex items-center gap-2">
            <div className="h-2 w-2 rounded-full bg-indigo-500 animate-pulse"></div>
            <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-wide">Sync Active</span>
         </div>
      </div>

      {/* 2. MAIN SPLIT CONTENT */}
      <div className="flex-1 flex gap-4 overflow-hidden min-h-0">
        
        {/* LEFT: TIMELINE (Replaces Calendar) */}
        <div className="flex-1 bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 shadow-sm flex flex-col overflow-hidden">
             
             {/* Balances Header (Like the Toolbar) */}
             <div className="flex-none px-6 py-4 border-b border-slate-100 dark:border-white/5 flex items-center justify-between bg-slate-50/50 dark:bg-white/[0.02]">
                <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">My Balances</span>
                <div className="flex gap-2">
                   {LEAVE_BALANCES.map(b => (
                      <div key={b.id} className="flex items-center gap-2 bg-white dark:bg-[#151515] pl-1 pr-3 py-1 rounded-full border border-slate-200 dark:border-white/5 shadow-sm">
                         <div className={`h-5 w-5 rounded-full flex items-center justify-center ${b.bg} ${b.color}`}>
                            <b.icon size={10} strokeWidth={3} />
                         </div>
                         <div className="flex items-baseline gap-1">
                            <span className="text-[10px] font-bold text-slate-900 dark:text-white">{b.total - b.used}</span>
                            <span className="text-[8px] font-bold text-slate-400">/ {b.total}</span>
                         </div>
                      </div>
                   ))}
                </div>
             </div>

             {/* Scrollable Request List */}
             <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                {MY_REQUESTS.map(req => {
                   const isSelected = selectedId === req.id;
                   const bal = getBalance(req.category);
                   
                   return (
                      <button 
                        key={req.id}
                        onClick={() => setSelectedId(req.id)}
                        className={`w-full text-left p-3 rounded-2xl border transition-all group relative overflow-hidden flex items-center gap-4 ${
                           isSelected 
                             ? "bg-slate-900 dark:bg-indigo-600 border-slate-900 dark:border-indigo-600 shadow-xl shadow-indigo-500/20 text-white" 
                             : "bg-white dark:bg-[#151515] border-slate-100 dark:border-white/5 hover:border-indigo-300"
                        }`}
                      >
                         {/* Date Block */}
                         <div className={`flex-shrink-0 w-12 h-12 rounded-xl flex flex-col items-center justify-center border ${
                            isSelected ? "bg-white/10 border-white/10" : "bg-slate-50 dark:bg-white/5 border-slate-100 dark:border-white/5"
                         }`}>
                            <span className={`text-[8px] font-black uppercase ${isSelected ? "text-white/60" : "text-slate-400"}`}>{getMonth(req.start)}</span>
                            <span className={`text-base font-black leading-none ${isSelected ? "text-white" : "text-slate-900 dark:text-white"}`}>{getDay(req.start)}</span>
                         </div>

                         {/* Info */}
                         <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-center mb-0.5">
                               <span className={`text-xs font-bold ${isSelected ? "text-white" : "text-slate-900 dark:text-white"}`}>{req.type}</span>
                               <span className={`text-[9px] font-black uppercase px-1.5 py-0.5 rounded ${
                                  isSelected ? "bg-white/20 text-white" : getStatusColor(req.status)
                               }`}>{req.status}</span>
                            </div>
                            <div className="flex items-center gap-2">
                               <div className={`w-1 h-1 rounded-full ${isSelected ? "bg-white/50" : bal.color.replace('text-', 'bg-')}`} />
                               <p className={`text-[10px] truncate ${isSelected ? "text-white/60" : "text-slate-500"}`}>{req.reason}</p>
                            </div>
                         </div>
                         
                         <ChevronRight size={14} className={`opacity-0 group-hover:opacity-100 transition-opacity ${isSelected ? "text-white" : "text-slate-300"}`} />
                      </button>
                   );
                })}
             </div>
        </div>

        {/* RIGHT: DETAILS & ACTION (Matches Sidebar Form) */}
        <div className="w-[380px] bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 flex flex-col shadow-xl overflow-hidden">
           
           {/* Header Context */}
           <div className="p-6 border-b border-slate-50 dark:border-white/5 bg-slate-50/50 dark:bg-white/[0.02]">
              <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest mb-1">Request ID</p>
                    <p className="text-xs font-bold text-slate-900 dark:text-white font-mono">{selectedReq.id}</p>
                 </div>
                 <div className="text-right">
                    <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest mb-1">Applied On</p>
                    <p className="text-xs font-bold text-slate-900 dark:text-white">{selectedReq.applied}</p>
                 </div>
              </div>
              
              <div className="bg-white dark:bg-[#151515] rounded-2xl p-4 border border-slate-100 dark:border-white/5 flex items-center justify-between shadow-sm">
                 <div>
                    <p className="text-[9px] font-black uppercase text-slate-400">Total Days</p>
                    <p className="text-2xl font-black text-slate-900 dark:text-white mt-1">{selectedReq.days}</p>
                 </div>
                 <div className="h-8 w-[1px] bg-slate-100 dark:bg-white/10" />
                 <div className="text-right">
                    <p className="text-[9px] font-black uppercase text-slate-400">Status</p>
                    <div className="flex items-center gap-1.5 mt-2 justify-end">
                       {selectedReq.status === 'Approved' && <CheckCircle2 size={14} className="text-emerald-500" />}
                       {selectedReq.status === 'Rejected' && <XCircle size={14} className="text-rose-500" />}
                       {selectedReq.status === 'Pending' && <Clock size={14} className="text-amber-500" />}
                       <span className="text-sm font-bold">{selectedReq.status}</span>
                    </div>
                 </div>
              </div>
           </div>

           {/* Content Body */}
           <div className="flex-1 p-6 space-y-6 overflow-y-auto">
              
              {/* Date Visualization */}
              <div>
                 <label className="text-[9px] font-black uppercase text-slate-400 mb-2 block tracking-widest">Timeline</label>
                 <div className="flex items-center gap-2">
                    <div className="flex-1 bg-slate-50 dark:bg-white/5 p-3 rounded-xl border border-slate-100 dark:border-white/5 flex items-center gap-3">
                       <Calendar size={14} className="text-indigo-500"/>
                       <span className="text-xs font-bold">{selectedReq.start}</span>
                    </div>
                    <ArrowUpRight size={14} className="text-slate-300"/>
                    <div className="flex-1 bg-slate-50 dark:bg-white/5 p-3 rounded-xl border border-slate-100 dark:border-white/5 flex items-center gap-3">
                       <Calendar size={14} className="text-indigo-500"/>
                       <span className="text-xs font-bold">{selectedReq.end}</span>
                    </div>
                 </div>
              </div>

              {/* Approval Flow (Visual) */}
              <div>
                 <label className="text-[9px] font-black uppercase text-slate-400 mb-3 block tracking-widest">Approval Chain</label>
                 <div className="relative pl-4 space-y-6 border-l border-slate-200 dark:border-white/10 ml-2">
                    {selectedReq.approvers.map((p, i) => (
                       <div key={i} className="relative">
                          <div className={`absolute -left-[21px] top-0 w-3 h-3 rounded-full border-2 border-white dark:border-[#111] ${
                             selectedReq.status === 'Approved' ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-white/20'
                          }`} />
                          <p className="text-xs font-bold leading-none">{p}</p>
                          <p className="text-[9px] font-medium text-slate-400 mt-1 uppercase">Reviewer {i+1}</p>
                       </div>
                    ))}
                 </div>
              </div>

              {/* Reason */}
              <div>
                 <label className="text-[9px] font-black uppercase text-slate-400 mb-2 block tracking-widest">Reason</label>
                 <div className="p-4 bg-slate-50 dark:bg-white/5 rounded-2xl border border-slate-100 dark:border-white/5 text-xs font-medium leading-relaxed text-slate-600 dark:text-slate-300">
                    "{selectedReq.reason}"
                 </div>
              </div>
           </div>

           {/* Footer Actions */}
           <div className="p-5 border-t border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/[0.02]">
              {selectedReq.status === 'Pending' ? (
                 <div className="grid grid-cols-2 gap-3">
                    <button className="py-3.5 rounded-xl border border-slate-200 dark:border-white/10 font-bold text-xs uppercase tracking-wider text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-white/5 transition-all flex items-center justify-center gap-2">
                       <Edit2 size={14} /> Edit
                    </button>
                    <button className="py-3.5 rounded-xl bg-rose-50 dark:bg-rose-900/20 border border-rose-100 dark:border-rose-900/30 font-bold text-xs uppercase tracking-wider text-rose-600 hover:bg-rose-100 dark:hover:bg-rose-900/30 transition-all flex items-center justify-center gap-2">
                       <Trash2 size={14} /> Withdraw
                    </button>
                 </div>
              ) : (
                 <button disabled className="w-full py-3.5 rounded-xl bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/5 font-bold text-xs uppercase tracking-wider text-slate-400 flex items-center justify-center gap-2 cursor-not-allowed">
                    <ShieldCheck size={14} /> Request Locked
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
}